import {
  ComponentContext,
  ComponentFile,
  ComponentTemplate,
} from '@teambit/generator';
import { indexFile } from './files/index-file';
import { NodeEnv } from './files/node-env-bit-env';
import { envJson } from './files/env-jsonc';
import { oxlintConfigFile } from './files/config/oxlintrc';
import { tsConfigFile } from './files/config/tsconfig.json';
// import { jestConfigFile } from './files/config/jest.config';
import { prettierConfigFile } from './files/config/prettier.config';
import { rspackTransformerFile } from './files/config/rspack-transformer';
import { envDtsFile } from './files/types/env';
import { vitestFile } from './files/config/vitest.config';
import { envDocsFile } from './files/docs';

export type NodeEnvTemplateOptions = {
  /**
   * name of the template
   */
  name?: string;

  /**
   * description of the template.
   */
  description?: string;

  /**
   * hide the template from the `bit templates` command.
   */
  hidden?: boolean;
};

export class NodeEnvTemplate implements ComponentTemplate {
  constructor(
    readonly name = 'node-env',
    readonly description = 'create a customized nodejs dev environment',
    readonly hidden = false,
    readonly env = 'bitdev.general/envs/bit-env',
    readonly isEnv = true,
    readonly installMissingDependencies = true
  ) {}

  generateFiles(context: ComponentContext): ComponentFile[] {
    return [
      indexFile(context),
      NodeEnv(context),
      envJson(),
      oxlintConfigFile(),
      tsConfigFile(),
      // jestConfigFile(),
      prettierConfigFile(),
      rspackTransformerFile(),
      envDtsFile(),
      envDocsFile(context),
      vitestFile()
    ];
  }

  static from(options: NodeEnvTemplateOptions = {}) {
    return () =>
      new NodeEnvTemplate(options.name, options.description, options.hidden);
  }
}
